S = "meyersound-galaxy"
# Meyer Sound GALAXY text protocol (Programming Guide Rev B4): one command per line,
# <path>=<value> to set, <path> to read, +<path> <ms> to subscribe, :function for built-ins.

text(S, "set_input_gain", {'input': 1, 'gain_db': -90.0}, "/processing/input/1/gain=-90.00\n")
text(S, "set_input_mute", {'input': 1, 'muted': True}, "/processing/input/1/mute=true\n")
text(S, "set_input_delay", {'input': 2, 'delay': 10.0}, "/processing/input/2/delay=10.00\n")
text(S, "set_input_eq_bypass", {'input': 1, 'bypassed': False}, "/processing/input/1/eq/bypass=false\n")
text(S, "set_input_ushaping_bypass", {'input': 1, 'bypassed': True}, "/processing/input/1/ushaping/bypass=true\n")
text(S, "set_output_gain", {'output': 16, 'gain_db': -3.5}, "/processing/output/16/gain=-3.50\n")
text(S, "set_output_mute", {'output': 1, 'muted': False}, "/processing/output/1/mute=false\n")
text(S, "set_output_delay", {'output': 3, 'delay': 1.5}, "/processing/output/3/delay=1.50\n")
text(S, "set_output_polarity", {'output': 1, 'reversed': True}, "/processing/output/1/polarity_reversal=true\n")
text(S, "set_output_eq_bypass", {'output': 1, 'bypassed': True}, "/processing/output/1/eq/bypass=true\n")
text(S, "set_output_ushaping_bypass", {'output': 1, 'bypassed': False}, "/processing/output/1/ushaping/bypass=false\n")
text(S, "set_output_highpass_bypass", {'output': 1, 'bypassed': False}, "/processing/output/1/highpass/bypass=false\n")
text(S, "set_output_highpass_frequency", {'output': 1, 'hz': 40.0}, "/processing/output/1/highpass/frequency=40.00\n")
text(S, "set_output_lowpass_bypass", {'output': 1, 'bypassed': True}, "/processing/output/1/lowpass/bypass=true\n")
text(S, "set_output_lowpass_frequency", {'output': 1, 'hz': 160.0}, "/processing/output/1/lowpass/frequency=160.00\n")
text(S, "set_output_atmospheric_bypass", {'output': 1, 'bypassed': True}, "/processing/output/1/atmospheric/bypass=true\n")
text(S, "set_matrix_gain", {'matrix_input': 1, 'output': 9, 'gain_db': 0.0}, "/processing/matrix/1/9/gain=0.00\n")
text(S, "set_matrix_delay", {'matrix_input': 2, 'output': 1, 'delay': 5.0}, "/processing/matrix/2/1/delay=5.00\n")
text(S, "set_matrix_delay_bypass", {'matrix_input': 2, 'output': 1, 'bypassed': True}, "/processing/matrix/2/1/delay_bypass=true\n")
text(S, "set_input_name", {'input': 1, 'name': 'Vox'}, "/device/input/1/name=Vox\n")
text(S, "set_output_name", {'output': 1, 'name': 'Main L'}, "/device/output/1/name=Main L\n")
text(S, "set_output_mute_relay", {'output': 1, 'engaged': True}, "/device/output/1/mute_relay=true\n")
text(S, "set_front_panel_lockout", {'locked': True}, "/system/hardware/front_panel_lockout=true\n")
text(S, "set_project_name", {'name': 'Tour'}, "/project/name=Tour\n")
text(S, "set_boot_snapshot", {'snapshot': 3}, "/project/boot_snapshot_id=3\n")
text(S, 'set_control_point', {'path': '/processing/input/[1-4]/mute', 'value': 'true'}, '/processing/input/[1-4]/mute=true\n')
text(S, 'get_control_point', {'path': '/processing/input/1/mute'}, '/processing/input/1/mute\n', device_reply="/processing/input/1/mute='false'\n", expect_result={'ok': {'kind': 'value', 'value': "'false'"}})
text(S, 'describe_control_point', {'path': '/processing/input/1/mute'}, '?/processing/input/1/mute\n', device_reply="?{'/processing/input/1/mute': { 'description' : 'Input 1 Mute', 'read_only' : 'false' }}\n", expect_result={'ok': {'kind': 'value', 'value': "?{'/processing/input/1/mute': { 'description' : 'Input 1 Mute', 'read_only' : 'false' }}"}})
text(S, 'subscribe', {'path': '/status/meter/output/.*', 'interval_ms': 50}, '+/status/meter/output/.* 50\n')
text(S, 'unsubscribe', {'path': '/status/meter/.*'}, '-/status/meter/.*\n')
text(S, 'recall_snapshot', {'snapshot': 3}, ':recall_snapshot 3\n')
text(S, 'recall_snapshot_excluding', {'snapshot': 3, 'exclude': 9}, ':recall_snapshot 3 9\n')
text(S, 'update_snapshot', {'snapshot': 2}, ':update_snapshot 2\n')
text(S, 'create_snapshot', {'name': 'Show', 'comment': 'Before doors'}, ':create_snapshot Show Before doors\n')
text(S, 'delete_snapshot', {'snapshot': 5}, ':delete_snapshot 5\n')
text(S, 'ping', {}, ':ping\n', device_reply=':pong\n', expect_result={'ok': {'kind': 'ack'}})
telemetry(S, 'point', inbound="/device/sim/probe/1/point='2'\n", expect_state={'points': {'/device/sim/probe/1/point': '2'}})
telemetry(S, "inputs-gain", inbound="/processing/input/1/gain='-6'\n", expect_state={**{'inputs': {'1': {'gain': -6.0}}}, 'points': {"/processing/input/1/gain": "-6"}})
telemetry(S, "inputs-mute", inbound="/processing/input/1/mute='true'\n", expect_state={**{'inputs': {'1': {'mute': True}}}, 'points': {"/processing/input/1/mute": "true"}})
telemetry(S, "inputs-delay", inbound="/processing/input/1/delay=2.5\n", expect_state={**{'inputs': {'1': {'delay': 2.5}}}, 'points': {"/processing/input/1/delay": "2.5"}})
telemetry(S, "outputs-gain", inbound="/processing/output/16/gain='0'\n", expect_state={**{'outputs': {'16': {'gain': 0.0}}}, 'points': {"/processing/output/16/gain": "0"}})
telemetry(S, "outputs-mute", inbound="/processing/output/2/mute=false\n", expect_state={**{'outputs': {'2': {'mute': False}}}, 'points': {"/processing/output/2/mute": "false"}})
telemetry(S, "outputs-delay", inbound="/processing/output/2/delay='1'\n", expect_state={**{'outputs': {'2': {'delay': 1.0}}}, 'points': {"/processing/output/2/delay": "1"}})
telemetry(S, "outputs-polarity-reversed", inbound="/processing/output/3/polarity_reversal='false'\n", expect_state={**{'outputs': {'3': {'polarity_reversed': False}}}, 'points': {"/processing/output/3/polarity_reversal": "false"}})
telemetry(S, "matrix-gain", inbound="/processing/matrix/1/9/gain='-90'\n", expect_state={**{'matrix': {'1': {'9': {'gain': -90.0}}}}, 'points': {"/processing/matrix/1/9/gain": "-90"}})
telemetry(S, "inputs-name", inbound="/device/input/1/name='Input A'\n", expect_state={**{'inputs': {'1': {'name': 'Input A'}}}, 'points': {"/device/input/1/name": "Input A"}})
telemetry(S, "outputs-name", inbound="/device/output/1/name='Output 1'\n", expect_state={**{'outputs': {'1': {'name': 'Output 1'}}}, 'points': {"/device/output/1/name": "Output 1"}})
telemetry(S, "meters-inputs", inbound="/status/meter/input/1='-90'\n", expect_state={**{'meters': {'inputs': {'1': -90.0}}}, 'points': {"/status/meter/input/1": "-90"}})
telemetry(S, "meters-outputs", inbound="/status/meter/output/4=-12.5\n", expect_state={**{'meters': {'outputs': {'4': -12.5}}}, 'points': {"/status/meter/output/4": "-12.5"}})
telemetry(S, "meters-matrix-inputs", inbound="/status/meter/matrix_input/9='-30'\n", expect_state={**{'meters': {'matrix_inputs': {'9': -30.0}}}, 'points': {"/status/meter/matrix_input/9": "-30"}})
telemetry(S, "device-model", inbound="/status/model_string='GX-816'\n", expect_state={"device": {"model": 'GX-816'}, 'points': {"/status/model_string": "GX-816"}})
telemetry(S, "device-name", inbound="/entity/entity_name='GALAXY-18139889'\n", expect_state={"device": {"name": 'GALAXY-18139889'}, 'points': {"/entity/entity_name": "GALAXY-18139889"}})
telemetry(S, "device-firmware", inbound="/entity/firmware_version='2.1.0-R4-1907032112'\n", expect_state={"device": {"firmware": '2.1.0-R4-1907032112'}, 'points': {"/entity/firmware_version": "2.1.0-R4-1907032112"}})
telemetry(S, "device-serial", inbound="/entity/serial_number='18139889'\n", expect_state={"device": {"serial": '18139889'}, 'points': {"/entity/serial_number": "18139889"}})
telemetry(S, "snapshot-active-id", inbound="/project/snapshot/active/id='-1'\n", expect_state={"snapshot": {"active_id": -1}, 'points': {"/project/snapshot/active/id": "-1"}})
telemetry(S, "snapshot-active-name", inbound="/project/snapshot/active/name='No snapshot selected'\n", expect_state={"snapshot": {"active_name": 'No snapshot selected'}, 'points': {"/project/snapshot/active/name": "No snapshot selected"}})
telemetry(S, "snapshot-active-modified", inbound="/project/snapshot/active/modified='true'\n", expect_state={"snapshot": {"active_modified": True}, 'points': {"/project/snapshot/active/modified": "true"}})
telemetry(S, "project-name", inbound="/project/name='Default'\n", expect_state={"project": {"name": 'Default'}, 'points': {"/project/name": "Default"}})
